function maxSpellDamage(power: number[]): number {
  const cnt = new Map<number, number>();
  for (const p of power) cnt.set(p, (cnt.get(p) ?? 0) + 1);
  const v = [...cnt.keys()].sort((a, b) => a - b);
  let best = 0;
  const go = (i: number, lastTaken: number, sum: number): void => {
    if (i === v.length) { best = Math.max(best, sum); return; }
    go(i + 1, lastTaken, sum);
    if (v[i] - lastTaken > 2) go(i + 1, v[i], sum + v[i] * cnt.get(v[i])!);
  };
  go(0, -Infinity, 0);
  return best;
}

