    def maxSpellDamage(self, power: List[int]) -> int:
        cnt = Counter(power)
        v = sorted(cnt)
        best = 0

        def go(i, last, s):
            nonlocal best
            if i == len(v):
                best = max(best, s)
                return
            go(i + 1, last, s)
            if v[i] - last > 2:
                go(i + 1, v[i], s + v[i] * cnt[v[i]])

        go(0, -math.inf, 0)
        return best

