function maxSpellDamage(power: number[]): number {
  const cnt = new Map<number, number>();
  for (const p of power) cnt.set(p, (cnt.get(p) ?? 0) + 1);
  const v = [...cnt.keys()].sort((a, b) => a - b);
  const best = new Array(v.length + 1).fill(0); // best[i] = answer using v[0..i-1]
  let j = 0;
  for (let i = 0; i < v.length; i++) {
    while (v[j] < v[i] - 2) j++;
    best[i + 1] = Math.max(best[i], best[j] + v[i] * cnt.get(v[i])!);
  }
  return best[v.length];
}

